    'আপনার প্রোফাইল, পোস্ট, রিল, স্টোরি, মন্তব্য আর আপনার পাঠানো বার্তা, আপনার ছবি ও ভিডিও, ফলোয়ার ও যাঁদের ফলো করেন, বন্ধু, সার্কেল, ঘনিষ্ঠ বন্ধু, আগ্রহ আর সহকারীর মেমরি। সব জায়গা থেকে আপনাকে সাইন আউট করা হয় আর আপনার ডিভাইসে বিজ্ঞপ্তি আসা বন্ধ হয়।',
